class LRUCache:
    """
    This class implements an LRU Cache using a hashmap for O(1) access to cache entries 
    along with a circular queue to manage the order of usage, ensuring efficient eviction 
    of the least recently used items.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key: int) -> int:
        if key in self.cache:
            self.order.remove(key)  # Remove key from its current position
            self.order.append(key)   # Move key to the end as most recently used
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache[key] = value
            self.order.remove(key)  # Remove key from its current position
            self.order.append(key)   # Move key to the end as most recently used
        else:
            if len(self.cache) >= self.capacity:
                lru_key = self.order.pop(0)  # Evict the least recently used item
                del self.cache[lru_key]
            self.cache[key] = value
            self.order.append(key)  # Add new key as most recently used

